// Requires: mesh OBJ (File → Open Mesh OBJ)
// Vertex layout: position (float3), normal (float3), UV (float2)

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSIn {
    [[vk::location(0)]] float3 pos : POSITION;
    [[vk::location(1)]] float3 nrm : NORMAL;
    [[vk::location(2)]] float2 uv  : TEXCOORD0;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 worldNrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv : TEXCOORD1;
    [[vk::location(2)]] float3 worldPos : TEXCOORD2;
};

float4x4 lookAtRH(float3 eye, float3 at, float3 up)
{
    float3 zaxis = normalize(eye - at);
    float3 xaxis = normalize(cross(up, zaxis));
    float3 yaxis = cross(zaxis, xaxis);
    return float4x4(
        float4(xaxis, -dot(xaxis, eye)),
        float4(yaxis, -dot(yaxis, eye)),
        float4(zaxis, -dot(zaxis, eye)),
        float4(0, 0, 0, 1)
    );
}

float4x4 perspectiveRH(float fovY, float aspect, float zn, float zf)
{
    float f = 1.0f / tan(fovY * 0.5f);
    return float4x4(
        float4(f / aspect, 0, 0, 0),
        float4(0, f, 0, 0),
        float4(0, 0, zf / (zn - zf), (zn * zf) / (zn - zf)),
        float4(0, 0, -1, 0)
    );
}

VSOut VSMain(VSIn i)
{
    VSOut o;
    float yaw = drag_accum_x * 0.01;
    float pitch = clamp(-drag_accum_y * 0.01, -1.4, 1.4);
    float dist = max(0.5, 3.0 - scroll_accum_y * 0.3);
    float3 fwd = float3(sin(yaw)*cos(pitch), sin(pitch), cos(yaw)*cos(pitch));
    float3 right = normalize(cross(float3(0,1,0), fwd));
    float3 up = cross(fwd, right);
    float panScale = dist * 0.002;
    float3 at = right * (-pan_accum_x * panScale) + up * (pan_accum_y * panScale);
    float3 eye = at + float3(dist * cos(pitch) * sin(yaw), dist * sin(pitch), dist * cos(pitch) * cos(yaw));
    float4x4 V = lookAtRH(eye, at, float3(0, 1, 0));
    float aspect = max(0.001, resolution_x / max(1.0, resolution_y));
    float4x4 P = perspectiveRH(radians(60.0), aspect, 0.05, 100.0);
    o.pos = mul(P, mul(V, float4(i.pos, 1.0)));
    o.worldNrm = normalize(i.nrm);
    o.uv = i.uv;
    o.worldPos = i.pos;
    return o;
}

// Requires: normal map texture (add via Textures panel, slot 0)
// Binds as combined image sampler: [[vk::combinedImageSampler]] [[vk::binding(0, 1)]]

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

[[vk::combinedImageSampler]] [[vk::binding(0, 1)]]
Texture2D normalMap : register(t0);
[[vk::combinedImageSampler]] [[vk::binding(0, 1)]]
SamplerState samp0 : register(s0);

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 worldNrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv : TEXCOORD1;
    [[vk::location(2)]] float3 worldPos : TEXCOORD2;
};

float4 PSMain(VSOut i) : SV_Target
{
    float3 N = normalize(i.worldNrm);
    float3 T = normalize(ddx(i.worldPos));
    float3 B = normalize(cross(N, T));
    float3x3 TBN = float3x3(T, B, N);
    float3 nm = normalMap.Sample(samp0, i.uv).xyz * 2.0 - 1.0;
    float3 perturbedN = normalize(mul(nm, TBN));
    float3 lightDir = normalize(float3(0.5, 0.7, 0.3));
    float diff = max(dot(perturbedN, lightDir), 0.0);
    float3 col = float3(0.8, 0.8, 0.8) * (0.15 + 0.85 * diff);
    return float4(col, 1.0);
}
